+    `M ${chartCoords[0].x} ${svgHeight-svgPadding} L ${chartCoords.map(p=>p.x+" "+p.y).join(" L ")} L ${chartCoords.at(-1)!.x} ${svgHeight-svgPadding} Z`:"";
+  const marker=chartCoords[crossSection.currentNodeIndex]??null;
