+    const ridges=reliefNoiseV150(x,y,width,height,options.seed);
+    const weight=biomeWeights[biomes[region-1]];
+    const amount=ramp*weight*(.72-.35*options.ruggedness+
+      (.2+.7*options.ruggedness)*ridges);
