+    highest=Math.max(highest,meters);
+  }
+  return {
+    width,height,maxElevationMeters:options.maxElevationMeters,radiusKm,rg16,preview,
+    landPixels,waterPixels,highestElevationMeters:highest,
+    regions:landStats.map(entry=>({
