+
+export function clearPlanetVisualProfileV134(
+  planet: WarPlanetV96, store: Pick<PlanetVisualStoreV134, "removeItem">,
+): boolean {
+  try {
+    store.removeItem(planetVisualStorageKeyV134(planet));
